{
  "jsonrpc": "2.0",
  "method": "call",
  "params": {
    "model": "loan.payment",
    "method": "search_read",
    "args": [
      [
        ["loan_id", "!=", false], // SOLO PARA ASEGURAR QUE EL PAGO PERTENEZCA A UN PRESTAMO
        ["loan_id.partner_salesperson", "=", 6], // ESTE ES EL FILTRO POR UID
        ["payment_date", ">=", "2025-05-01"],  // FECHA INICIAL DEL RANGO
        ["payment_date", "<=", "2025-05-30"],  // FECHA FINAL DEL RANGO
        ["payment_status" , "=", "pending"] // SOLO LOS PAGOS PENDING. CUALQUIERO OTRO ESTADO SE QUITA
      ],
      ["loan_id", "payment_date"]
    ],
    "kwargs": {}
  }
}

{
  "jsonrpc": "2.0",
  "method": "call",
  "params": {
    "service": "object",
    "method": "execute",
    "args": [
      "prestamovf",  // Nombre de la base de datos
      6,                   // UID del usuario (lo puedes obtener desde la autenticación)
      "1234",    // Contraseña del usuario
      "loan.management",   // Nombre del modelo (tabla)
      "search_read",       // Método para realizar la búsqueda y leer los datos
      [
        ["loan_status", "=", "pending"],     // Filtro para obtener solo los registros con loan_status == 'pending'
        ["partner_salesperson.id", "=", 6],
        ["name", "=", "PRST-00003"]  // Filtro para que solo se obtengan los prestamos de este gestor con UID obtenido en el login

      ],
      [
        "id", "partner_latitude", "partner_longitude"
      ]
    ]
  }
}
